<?php if(!isset($listing,$message,$escape,$url)){http_response_code(404);exit;}?><section class="approval-panel"><?php if($message):?><p class="approval-message success"><?= $escape($message) ?></p><?php endif;?><h2>Phản ánh chờ xử lý</h2><div class="payment-table-scroll"><table class="payment-table"><thead><tr><th>STT</th><th>Mã phản ánh</th><th>Thời gian gửi</th><th>Phòng</th><th>Sinh viên</th><th>Loại sự cố</th><th>Thao tác</th></tr></thead><tbody><?php foreach($listing['items'] as $i=>$item):?><tr><td><?=($listing['page']-1)*20+$i+1?></td><td><?= $escape($item['MaPhanAnh']) ?></td><td><?= $escape($item['ThoiGianGui']) ?></td><td><?= $escape($item['SoPhong']) ?></td><td><?= $escape($item['MSSV'].' · '.$item['HoTen']) ?></td><td><?= $escape($item['LoaiSuCo']) ?></td><td><a class="approval-button" href="<?= $url('index.php?action=incident-detail&id='.rawurlencode($item['MaPhanAnh'])) ?>">Xử lý</a></td></tr><?php endforeach;?><?php if(!$listing['items']):?><tr><td colspan="7">Không có phản ánh đang chờ xử lý.</td></tr><?php endif;?></tbody></table></div><p>Tổng <?= $listing['total'] ?> phản ánh · Trang <?= $listing['page'] ?>/<?= $listing['pages'] ?></p><nav class="incident-pagination"><?php if($listing['page']>1):?><a class="approval-button" href="<?= $url('index.php?action=incidents&page='.($listing['page']-1)) ?>">Trang trước</a><?php endif;?><?php if($listing['page']<$listing['pages']):?><a class="approval-button" href="<?= $url('index.php?action=incidents&page='.($listing['page']+1)) ?>">Trang sau</a><?php endif;?></nav></section>
